function setTool(t){tool=t;$$('.tool').forEach(b=>b.classList.toggle('active',b.dataset.tool===t));const names={move:['MOVE / INTERACT','UTILITY','∞'],pistol:['SIDEARM','9MM / SEMI-AUTO','∞'],rifle:['PULSE RIFLE','ENERGY / BURST','∞'],stun:['SHOCK TOOL','NON-LETHAL','∞'],gravity:['GRAVITY GLOVE','FIELD / MANIPULATE','∞']};$('#weaponName').textContent=names[t][0];$('#weaponMeta').textContent=names[t][1];$('#ammoText').textContent=names[t][2];$('#ammoBar').style.width=t==='move'||t==='gravity'?'100%':'76%';if(t==='gravity')toast('Gravity field ready')}
$$('.tool').forEach(b=>b.addEventListener('click',()=>{setTool(b.dataset.tool);$('#sidebar').classList.remove('open')}));
$$('.spawn').forEach(b=>b.addEventListener('click',()=>spawn(b.dataset.spawn)));$$('.mach').forEach(b=>b.addEventListener('click',()=>{if(b.id==='clearBtn'){reset();return}let k=b.dataset.machine;systems[k]=!systems[k];b.classList.toggle('on',systems[k]);if(k==='alarm'){alarm=systems.alarm;toast(alarm?'Alarm armed':'Alarm silenced')}else toast(`${b.textContent.trim().replace(/^[◁⌖◉♬▤]\s*/, '')} ${systems[k]?'online':'offline'}`)}));
$('#pauseBtn').onclick=()=>togglePause();$('#resumeBtn').onclick=()=>togglePause();function togglePause(){paused=!paused;$('#pauseOverlay').classList.toggle('show',paused);$('#pauseBtn').textContent=paused?'▶':'Ⅱ'}$('#slowBtn').onclick=()=>{slow=!slow;$('#slowBtn').classList.toggle('active',slow);toast(slow?'Slow motion · 30%':'Normal speed')};$('#gridBtn').onclick=()=>{showGrid=!showGrid;$('#gridBtn').classList.toggle('active',!showGrid)};$('#soundBtn').onclick=()=>{soundOn=!soundOn;$('#soundBtn').classList.toggle('active',soundOn);toast(soundOn?'Sound enabled':'Sound muted')};$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');
const keys={};window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.repeat)return;let k=e.key.toLowerCase();if(k==='q')setTool('move');if(k==='1')setTool('pistol');if(k==='2')setTool('rifle');if(k==='3')setTool('stun');if(k==='4')setTool('gravity');if(k==='r')reset();if(k==='t')$('#slowBtn').click();if(k==='g')$('#gridBtn').click();if(k==='m')$('#soundBtn').click();if(k==='escape')togglePause();if(k==='e')throwGrenade()});window.addEventListener('keyup',e=>keys[e.code]=false);
function aimAt(e){const r=canvas.getBoundingClientRect();pointer.x=e.clientX-r.left+camX;pointer.y=e.clientY-r.top+camY;player.face=pointer.x>=player.x?1:-1}
canvas.addEventListener('pointermove',e=>{aimAt(e);if(dragged){dragged.x=pointer.x-dragOff.x;dragged.y=pointer.y-dragOff.y;dragged.vx=dragged.vy=0}});canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);aimAt(e);pointer.down=true;const near=findNear(pointer.x,pointer.y,75);if(tool==='move'||tool==='gravity'){if(near){dragged=near;dragOff.x=pointer.x-near.x;dragOff.y=pointer.y-near.y}}else fire()});canvas.addEventListener('pointerup',()=>{pointer.down=false;if(dragged){const dx=pointer.x-dragged.x;dragged.vx=dx*4;dragged.vy=-70;dragged=null}});
function findNear(x,y,range){let list=[...npcs.filter(n=>!n.dead),...props];let best=null,bd=range;for(const o of list){let d=Math.hypot(x-o.x,y-o.y);if(d<bd){bd=d;best=o}}return best}
function fire(){if(tool==='move'||tool==='gravity'){let o=findNear(pointer.x,pointer.y,52);if(o&&!dragged){dragged=o;dragOff={x:pointer.x-o.x,y:pointer.y-o.y}}return}if(triggerCooldown>0)return;triggerCooldown=tool==='rifle'?.11:tool==='stun'?.6:.32;const angle=Math.atan2(pointer.y-(player.y-28),pointer.x-player.x);player.face=Math.cos(angle)>=0?1:-1;if(tool==='stun'){let target=null,dist=380;for(const n of npcs){if(n.dead)continue;let d=Math.hypot(n.x-player.x,n.y-player.y);if(d<dist){dist=d;target=n}}if(target){target.stun=2.8;target.vx+=Math.cos(angle)*230;target.vy-=90;for(let i=0;i<8;i++)particles.push({x:target.x,y:target.y-20,vx:(Math.random()-.5)*190,vy:(Math.random()-.5)*190,color:'#66e8e4',life:.45,size:2+Math.random()*3});toast('Subject stunned')}return}let speed=tool==='rifle'?820:690;bullets.push({x:player.x+Math.cos(angle)*23,y:player.y-30+Math.sin(angle)*23,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,life:1.1,damage:tool==='rifle'?40:34,color:tool==='rifle'?'#9cf8df':'#ffc878',r:tool==='rifle'?3:2.5});for(let i=0;i<3;i++)particles.push({x:player.x+Math.cos(angle)*24,y:player.y-30+Math.sin(angle)*24,vx:Math.cos(angle)*120+(Math.random()-.5)*50,vy:Math.sin(angle)*120+(Math.random()-.5)*50,color:'#ffdb9a',life:.12,size:2+Math.random()*2})}
function throwGrenade(){if(grenades.length>4)return;let dir=player.face;grenades.push({x:player.x+dir*22,y:player.y-38,vx:dir*360,vy:-370,t:2.4,r:8});toast('Shock charge thrown')}
$('#fireTouch').addEventListener('pointerdown',e=>{e.preventDefault();touchFire=true;if(tool!=='move'&&tool!=='gravity')fire();else{let o=findNear(player.x+player.face*55,player.y-28,80);if(o){dragged=o;dragOff={x:player.x-o.x,y:player.y-30-o.y}}}});$('#fireTouch').addEventListener('pointerup',()=>{touchFire=false;if(dragged){dragged.vx=player.face*360;dragged.vy=-80;dragged=null}});$('#fireTouch').addEventListener('pointercancel',()=>touchFire=false);$('#jumpTouch').addEventListener('pointerdown',e=>{e.preventDefault();jump()});$('#grabTouch').addEventListener('pointerdown',e=>{e.preventDefault();if(tool==='move')setTool('gravity');else setTool('move')});
const stick=$('#stick'),knob=$('#knob');stick.addEventListener('pointerdown',e=>{stick.setPointerCapture(e.pointerId);moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.buttons||e.pressure)moveStick(e)});stick.addEventListener('pointerup',()=>{joystick={x:0,y:0};knob.style.transform='translate(0,0)'});function moveStick(e){let r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),m=Math.min(36,Math.hypot(dx,dy)),a=Math.atan2(dy,dx);joystick.x=Math.cos(a)*m/36;joystick.y=Math.sin(a)*m/36;knob.style.transform=`translate(${joystick.x*36}px,${joystick.y*36}px)`}
function jump(){if(player.onGround){player.vy=-470;player.onGround=false}}

function step(dt){triggerCooldown=Math.max(0,triggerCooldown-dt);if(pointer.down&&tool!=='move'&&tool!=='gravity'&&tool!=='stun')fire();if(touchFire&&tool!=='move'&&tool!=='gravity'&&tool!=='stun')fire();if(paused)return;dt*=slow?.3:1;
 let ix=(keys.KeyA||keys.ArrowLeft?-1:0)+(keys.KeyD||keys.ArrowRight?1:0)+joystick.x;ix=Math.max(-1,Math.min(1,ix));if(ix)player.face=Math.sign(ix);player.vx+=(ix*420-player.vx)*Math.min(1,dt*9);if((keys.Space||keys.KeyW||keys.ArrowUp)&&player.onGround)jump();player.vy+=1250*dt;player.x+=player.vx*dt;player.y+=player.vy*dt;player.x=Math.max(35,Math.min(WORLD.w-35,player.x));player.onGround=false;solvePlayer();player.invuln=Math.max(0,player.invuln-dt);
 for(const n of npcs){if(n.dead){n.decay+=dt;continue}n.stun=Math.max(0,n.stun-dt);n.walk+=dt*(2+Math.abs(n.vx)*.02);if(n.stun<=0){if(n.type==='bot'){n.vx+=(Math.sin(n.walk*1.6)*35-n.vx)*dt*.6}else{if(Math.random()<dt*.5)n.face=Math.random()<.5?-1:1;let toward=player.x-n.x;n.vx+=(n.type==='guard'&&Math.abs(toward)<320?Math.sign(toward)*48:n.face*(n.type==='guard'?22:34)-n.vx)*dt*1.6;if(Math.random()<dt*.18&&Math.random()<.35)n.vy=-210}}
 n.vy+=1180*dt;n.x+=n.vx*dt;n.y+=n.vy*dt;n.vx*=Math.pow(.985,dt*60);n.x=Math.max(25,Math.min(WORLD.w-25,n.x));n.ground=false;if(n.y+n.r*2>=WORLD.floor){n.y=WORLD.floor-n.r*2;n.vy=0;n.ground=true}for(const p of platforms){if(n.x>p.x-20&&n.x<p.x+p.w+20&&n.y+n.r*2>p.y&&n.y+n.r*2<p.y+30&&n.vy>=0){n.y=p.y-n.r*2;n.vy=0;n.ground=true}}if(n.type==='guard'&&systems.turret===false&&Math.abs(player.x-n.x)<0){/* passive guard */}}
 for(const p of props){p.vy+=1150*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.992,dt*60);if(p.y+p.h/2>WORLD.floor){p.y=WORLD.floor-p.h/2;p.vy*=-.2;p.vx*=.8}if(systems.conveyor&&p.y+p.h/2>=WORLD.floor-2&&p.x>970&&p.x<1220)p.vx+=75*dt}
 if(systems.conveyor){for(const n of npcs)if(!n.dead&&n.ground&&n.x>970&&n.x<1220)n.vx+=52*dt}
 if(systems.crusher){let cy=platforms[2].y+Math.sin(performance.now()*.0012)*105;platforms[2].y=cy;for(const n of npcs)if(!n.dead&&n.x>platforms[2].x&&n.x<platforms[2].x+platforms[2].w&&n.y+n.r*2>cy&&n.y<cy+5)damage(n,4,'#e68b75')}
 if(systems.turret&&Math.random()<dt*.9){let target=npcs.find(n=>!n.dead);if(target){const a=Math.atan2(target.y-30-495,target.x-1780);bullets.push({x:1780,y:495,vx:Math.cos(a)*530,vy:Math.sin(a)*530,life:1.6,damage:16,color:'#ff8a6c',r:3,hostile:true})}}
 for(let i=bullets.length-1;i>=0;i--){let b=bullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;let hit=false;if(b.hostile){let dx=player.x-b.x,dy=player.y-28-b.y;if(Math.hypot(dx,dy)<20){player.hp=Math.max(0,player.hp-8);hit=true;player.invuln=.3}}else for(const n of npcs){if(n.dead)continue;if(Math.hypot(n.x-b.x,n.y+n.r-b.y)<n.r+5){damage(n,b.damage,b.color);hit=true;break}}if(hit||b.life<=0||b.x<0||b.x>WORLD.w||b.y>WORLD.h||b.y<0){if(hit)impact(b.x,b.y,b.color);bullets.splice(i,1)}}
 for(let i=grenades.length-1;i>=0;i--){let g=grenades[i];g.t-=dt;g.vy+=680*dt;g.x+=g.vx*dt;g.y+=g.vy*dt;if(g.y>WORLD.floor-10){g.y=WORLD.floor-10;g.vy*=-.48;g.vx*=.82}if(g.t<=0){for(const n of npcs)if(!n.dead&&Math.hypot(n.x-g.x,n.y-g.y)<170){n.stun=2;n.vx+=(n.x-g.x)*3;n.vy-=180;damage(n,30,'#a5e5d8')}for(let j=0;j<30;j++)particles.push({x:g.x,y:g.y,vx:(Math.random()-.5)*430,vy:(Math.random()-.8)*400,color:j%2?'#a8ffe5':'#ffd78b',life:.8,size:2+Math.random()*5});grenades.splice(i,1)}}
 for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=400*dt;p.life-=dt;if(p.life<=0)particles.splice(i,1)}for(let i=blood.length-1;i>=0;i--){blood[i].life-=dt;if(blood[i].life<=0)blood.splice(i,1)}
 camX=Math.max(0,Math.min(WORLD.w-W,player.x-W*.48));camY=Math.max(0,Math.min(180,player.y-H*.63));updateCounts();}
function solvePlayer(){if(player.y+31>=WORLD.floor){player.y=WORLD.floor-31;player.vy=0;player.onGround=true}for(const p of platforms){if(player.x+13>p.x&&player.x-13<p.x+p.w&&player.y+31>p.y&&player.y+31<p.y+24&&player.vy>=0){player.y=p.y-31;player.vy=0;player.onGround=true}}}
function damage(n,amt,color){if(n.dead)return;n.hp-=amt;n.vx+=Math.sign(n.x-player.x)*55;n.vy-=35;for(let i=0;i<5;i++)particles.push({x:n.x,y:n.y+n.r,vx:(Math.random()-.5)*150,vy:-Math.random()*120,color:n.type==='bot'?'#65cde3':'#bd6c69',life:.45,size:1.5+Math.random()*3});if(n.hp<=0){n.dead=true;n.decay=0;n.vx*=.3;n.vy=-130;let c=n.type==='bot'?'#58b9ce':'#a95558';for(let i=0;i<22;i++)particles.push({x:n.x,y:n.y+n.r,vx:(Math.random()-.5)*280,vy:-Math.random()*220,color:c,life:1.2,size:2+Math.random()*5});blood.push({x:n.x,y:WORLD.floor-1,r:8+Math.random()*13,life:14,color:c});toast(n.type==='bot'?'Unit disabled':'Subject down');if(soundOn)beep(95,.09)}else if(soundOn)beep(160,.045)}
