let audioCtx;function beep(f,d){try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.frequency.value=f;o.type='square';g.gain.value=.025;g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+d);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+d)}catch{}}

function rr(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function draw(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);let grad=ctx.createLinearGradient(0,0,0,H);grad.addColorStop(0,'#1b2625');grad.addColorStop(.65,'#202928');grad.addColorStop(1,'#141a19');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);ctx.save();ctx.translate(-camX,-camY);drawRoom();for(const b of blood)drawBlood(b);drawMachines();for(const p of platforms)drawPlatform(p);for(const p of props)drawCrate(p);for(const n of npcs)drawNpc(n);drawPlayer();for(const g of grenades){ctx.fillStyle='#b9ee83';ctx.shadowColor='#b9ee83';ctx.shadowBlur=14;ctx.beginPath();ctx.arc(g.x,g.y,g.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}for(const b of bullets){ctx.fillStyle=b.color;ctx.shadowColor=b.color;ctx.shadowBlur=12;ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/1.2);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;if(showGrid)drawGrid();ctx.restore();drawVignette();requestAnimationFrame(frame)}
function drawRoom(){// architectural shell
 ctx.fillStyle='#202a28';ctx.fillRect(0,0,WORLD.w,WORLD.floor);ctx.fillStyle='#273331';ctx.fillRect(0,0,WORLD.w,20);ctx.fillStyle='#34403d';ctx.fillRect(0,20,WORLD.w,5);
 // backwall panel rhythm
 for(let x=0;x<WORLD.w;x+=180){ctx.fillStyle=x%360===0?'#222d2b':'#202a29';ctx.fillRect(x,27,176,WORLD.floor-27);ctx.strokeStyle='#303c39';ctx.lineWidth=1;ctx.strokeRect(x+12,65,152,325);ctx.strokeRect(x+12,410,152,150);ctx.fillStyle='#293634';ctx.fillRect(x+20,77,136,3);ctx.fillStyle='#35413e';ctx.fillRect(x+22,424,35,3);ctx.fillStyle='#4b5e54';ctx.fillRect(x+22,436,8,2);ctx.fillRect(x+35,436,5,2);}
 // lamps and pipes
 for(let x=110;x<WORLD.w;x+=360){ctx.fillStyle='#394542';ctx.fillRect(x,30,105,6);ctx.fillStyle=systems.lights?'#d8e6a8':'#53605a';ctx.shadowColor=systems.lights?'#d8e6a8':'transparent';ctx.shadowBlur=systems.lights?20:0;ctx.fillRect(x+9,37,86,3);ctx.shadowBlur=0;ctx.fillStyle='#718277';ctx.fillRect(x+3,17,5,28);ctx.fillRect(x+103,17,5,28)}
 ctx.fillStyle='#35423f';ctx.fillRect(0,WORLD.floor,WORLD.w,92);ctx.fillStyle='#46534d';ctx.fillRect(0,WORLD.floor,WORLD.w,5);ctx.fillStyle='#18201e';ctx.fillRect(0,WORLD.floor+5,WORLD.w,87);
