 for(let x=20;x<WORLD.w;x+=200){ctx.fillStyle='#7c7450';ctx.globalAlpha=.68;for(let j=0;j<4;j++){ctx.save();ctx.translate(x+j*12,WORLD.floor-6);ctx.rotate(-.8);ctx.fillRect(0,0,6,13);ctx.restore()}ctx.globalAlpha=1}
 // prominent chamber label
 ctx.save();ctx.globalAlpha=.45;ctx.fillStyle='#b6ce9c';ctx.font='800 10px ui-monospace,monospace';ctx.fillText('FERAL / BIO-MECHANICAL TEST FACILITY',58,105);ctx.fillStyle='#85958a';ctx.font='8px ui-monospace,monospace';ctx.fillText('AUTHORIZED PERSONNEL ONLY  •  CHAMBER 07',58,120);ctx.restore();
 // background wall monitors
