(() => {
'use strict';
const canvas=document.getElementById('gameCanvas'),ctx=canvas.getContext('2d'),stage=document.getElementById('stage');
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let W=0,H=0,dpr=1,camX=0,camY=0,last=0,paused=false,slow=false,showGrid=true,soundOn=false,alarm=false,toastTimer=0;
const WORLD={w:2200,h:900,floor:808};
let player={x:390,y:WORLD.floor-60,vx:0,vy:0,face:1,onGround:true,hp:100,invuln:0};
let npcs=[],props=[],bullets=[],particles=[],blood=[],tool='move',pointer={x:0,y:0,down:false},dragged=null,dragOff={x:0,y:0},joystick={x:0,y:0},touchFire=false,triggerCooldown=0,grenades=[],systems={conveyor:true,turret:false,lights:true,alarm:false,crusher:false};
const colors={worker:['#79cbb2','#4a8173'],guard:['#d49a68','#725943'],bot:['#7fc4da','#436b78']};
function resize(){const r=stage.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}window.addEventListener('resize',resize);resize();
function npc(type,x,y){return {type,x,y,vx:(Math.random()-.5)*35,vy:0,r:type==='bot'?18:15,hp:type==='guard'?120:100,max:type==='guard'?120:100,face:Math.random()<.5?-1:1,walk:Math.random()*10,ground:true,stun:0,dead:false,decay:0,fire:1+Math.random()*2,tag:Math.random()<.5?'UNIT':'SUBJECT'}}
function updateCounts(){const c=npcs.filter(n=>!n.dead).length;$('#npcCount').textContent=String(c).padStart(2,'0')+' / 12';$('#subjectRead').textContent=String(c+1).padStart(2,'0');$('#alertRead').textContent=alarm||c>7?'ELEVATED':c>3?'MED':'LOW'}
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1500)}
const platforms=[{x:160,y:638,w:250,h:18},{x:510,y:540,w:300,h:18},{x:880,y:650,w:210,h:18},{x:1230,y:550,w:280,h:18},{x:1640,y:640,w:300,h:18},{x:680,y:365,w:180,h:16},{x:1450,y:370,w:220,h:16}];
function spawn(type,x){if(type==='crate'){if(!x)x=camX+W*.65;props.push({type:'crate',x,y:WORLD.floor-30,w:54,h:54,vx:0,vy:0});toast('Crate deployed');return}if(npcs.filter(n=>!n.dead).length>=12){toast('Maximum 12 active subjects');return}if(!x)x=camX+W*.65;npcs.push(npc(type,x,WORLD.floor-(type==='bot'?20:50)));updateCounts();toast(`${type[0].toUpperCase()+type.slice(1)} deployed`)}
function reset(){npcs=[];props=[];bullets=[];particles=[];blood=[];grenades=[];player={x:390,y:WORLD.floor-60,vx:0,vy:0,face:1,onGround:true,hp:100,invuln:0};spawn('worker',690);spawn('guard',1080);spawn('bot',1580);props.push({type:'crate',x:775,y:WORLD.floor-28,w:54,h:54,vx:0,vy:0});updateCounts();toast('Chamber reset')}
reset();

